<template>
 <section class="refund-goods" v-loading="loading||busy">
  <div class="heading"><div><h3>本退款商品与货物进度</h3><p class="hint">以下数量仅属于当前TK。退款商品、已确认实收和库存入账分别跟踪；整个合包的仓库回传请进入包裹详情查看。</p></div><el-button v-hasPermi="['order:refund:goods']" size="small" @click="refresh">刷新本退款货物进度</el-button></div>
  <el-alert v-if="error" :title="error" type="warning" :closable="false" />
  <div class="toolbar"><el-tag :type="plans.some(planPending)?'warning':'info'">{{ plans.some(planPending)?'实收待分配':label(refund.goods_state) }}</el-tag><template v-if="refund.review_state==='APPROVED'&&refund.goods_state!=='DONE'&&(refund.platform.platform_status!=='CLOSED'||refund.funds_state==='SUCCESS')"><el-button v-if="refund.goods_action==='CANCEL'" v-hasPermi="['order:refund:goods']" size="small" @click="open('cancelUnshipped')">执行已审核未发取消</el-button><el-button v-if="returnRequired" v-hasPermi="['order:refund:goods']" size="small" type="primary" @click="open('create')">创建退回安排</el-button><el-button v-if="plans.length" v-hasPermi="['order:refund:goods']" size="small" @click="open('finish')">确认货物处理完成</el-button><el-button v-if="returnRequired&&!plans.length" v-hasPermi="['order:refund:close']" size="small" @click="open('waiveAll')">确认无需追回</el-button></template><el-button v-if="refund.platform.platform_status==='CLOSED'&&refund.goods_state!=='DONE'&&refund.funds_state!=='SUCCESS'" v-hasPermi="['order:refund:close']" size="small" @click="open('closeWithdrawn')">确认申请关闭后的货物处置</el-button><router-link :to="{path:'/oms-order/business',query:{view:'business',orderId:refund.order_id}}">原订单履约与截单</router-link><router-link :to="{path:'/oms-supplychain/wmsLogs',query:{numberType:'REFUND',number:refund.refund_sn,allTime:'true'}}">本退款仓库交互日志</router-link></div>
  <refund-parcel-issue-review ref="issueReview" :refund="refund" @changed="parcelChanged" @waive="startParcelWaive"/>
  <div v-if="plans.length" class="refund-overview"><b>当前退款单 {{ refund.refund_sn }}</b><div class="refund-metrics"><div><span>计划退回</span><strong>{{ total('quantity') }} 件</strong></div><div><span>本退款实收</span><strong :class="{'warning':plans.some(planPending)}">{{ receiptText(total('accepted_quantity'),plans.some(planPending)) }}</strong></div><div><span>已入账</span><strong>{{ total('posted_quantity') }} 件</strong></div><div><span>不再追回</span><strong>{{ total('waived_quantity') }} 件</strong></div></div><p v-if="plans.some(planPending)" class="warning">关联包裹有实收待分配，尚不能确定本退款收到多少；查看包裹后按原回传分配。</p></div>
  <el-empty v-if="!plans.length" :description="returnRequired?'尚未安排退回，请明确实际发货来源和应退数量':'当前方案无需退回；未发商品取消请在原订单核对库存与截单结果'" :image-size="65" />
  <article v-for="p in plans" :key="p.id" class="plan">
   <h4>退回计划 #{{ p.id }} · {{ p.sku_sn }} <el-tag size="mini">{{ planLabel(p.state) }}</el-tag></h4>
   <p class="hint">原发货单 {{ p.shipment_sn }} · 明细 #{{ p.shipment_line_id }} · {{ label(p.return_mode) }}<br>初始接收仓 {{ p.store_code }} · 初始寄回地址 {{ p.return_address }} · {{ p.return_contact }}<br>物流与运单在关联包裹的独立详情中管理 · 依据 {{ p.reason }} · 凭证 {{ p.evidence }}</p>
   <div class="totals">计划退回 <b>{{ p.quantity }}</b> · 本退款实收 <b>{{ receiptText(p.accepted_quantity,planPending(p)) }}</b> · 已入账 <b>{{ p.posted_quantity }}</b> · 不再追回 <b>{{ p.waived_quantity }}</b> · 尚未确认退回／差异处理 <b>{{ remaining(p) }}</b> 件</div>
   <el-alert v-if="pendingReviews(p).length" :title="`另有 ${pendingReviews(p).length} 条回传（${pendingQuantity(p)} 件）待人工核对，未计入实收和库存；请勿与待退回数量相加`" type="warning" show-icon :closable="false"/>
   <div v-if="sharedPlan(p)" class="toolbar"><span class="hint">本计划与关联退款共用THK；仓库原始回传、分配实收和共同截单统一在包裹详情处理。</span><el-button size="small" type="primary" @click="openParcel(p.id)">查看包裹及处理实收</el-button></div>
   <el-alert v-if="p.last_error" :title="p.last_error" type="warning" :closable="false" />
   <template v-if="!sharedPlan(p)">
   <p class="hint">下方是同一计划的逐次安排，旧单截停数量是当时的历史快照，不与新单数量相加。</p>
   <div v-if="activeDocuments(p).length" class="toolbar"><el-button v-hasPermi="['order:refund:goods']" size="small" @click="open('stop',p)">截停全部未完成安排（{{ activeDocuments(p).length }} 张）</el-button><span class="hint">仅停止本计划的后续收货，不撤销已实收入账；最终不再追回请另行处理差异。</span></div>
   <el-alert v-if="p.parcel_manual_dispatch&&p.state==='PLANNED'" title="已核对补充关联，下一步人工下发本退款退回单" description="原THK及已入账保留；新THK受理后再明确核对原包裹待分配实收，本次关联未增加库存。" type="info" :closable="false"/><div v-if="!p.actual" class="toolbar"><el-button v-if="p.state==='PLANNED'" v-hasPermi="['order:refund:goods']" size="small" type="primary" :disabled="parcelBlocked(p)" @click="command(p,null,'dispatch')">{{ p.parcel_manual_dispatch?'下发本退款补充退回单':'下发退回单至仓库' }}</el-button><el-button v-if="p.parcel_state==='NEED_CHECK'" v-hasPermi="['order:refund:goods']" size="small" @click="$refs.issueReview.open(p.id)">先核对合包归属</el-button><el-button v-if="p.state==='PLANNED'" v-hasPermi="['order:refund:goods']" size="small" @click="open('cancel',p)">停止本地安排</el-button><el-button v-if="p.state==='STOPPED'" v-hasPermi="['order:refund:goods']" size="small" @click="open('rearrange',p)">重新安排</el-button></div>
   <div v-for="d in documents(p)" :key="d.id" class="document"><div class="heading"><router-link :to="{path:'/oms-supplychain/wmsTickets',query:{sn:d.return_sn,documentId:d.ticket_id}}"><strong>{{ d.return_sn }}</strong></router-link><el-tag size="mini">第 {{ d.generation }} 次安排 · {{ dispatch(d) }}</el-tag></div><p>本次安排 {{ d.quantity }} · 已确认实收 {{ d.accepted_quantity }} · 已入账 {{ d.posted_quantity }} 件 <span v-if="d.cancel_state!=='CONFIRMED'">· 本单待收 {{ Math.max(0,Number(d.quantity)-Number(d.accepted_quantity)) }} 件</span></p><p v-if="documents(p).length>1" class="hint">{{ d.id===documents(p)[0].id?'最新一次安排，是否继续执行以本单状态为准':'此前安排；后续另有新单，点击新单查看当前执行进度' }}</p><p class="hint">仓库单号 {{ d.external_order||'待返回' }} · 仓库状态 {{ d.warehouse_status||'待处理' }}<br>本次接收仓 {{ d.store_code }} · {{ d.return_address }}<br><span v-if="d.cancelled_at">截停时剩余 {{ d.cancelled_quantity }} 件（历史快照，不是当前计划待退数量）；{{ d.cancel_reason }}</span></p><el-alert v-if="d.last_error" :title="d.last_error" type="warning" :closable="false" /><div class="toolbar"><el-button v-if="d.dispatch_state==='PENDING'&&d.cancel_state==='NONE'&&refund.goods_state!=='DONE'" v-hasPermi="['order:refund:goods']" size="small" type="primary" :disabled="pendingReviews(p).length>0||parcelBlocked(p)" @click="command(p,d,'dispatch')">下发本次退回单</el-button><el-button v-hasPermi="['order:refund:goods']" size="small" @click="command(p,d,'query')">查询仓库原单</el-button><el-button v-if="d.dispatch_state==='FAILED'&&d.cancel_state==='NONE'&&refund.goods_state!=='DONE'" v-hasPermi="['order:refund:goods']" size="small" :disabled="pendingReviews(p).length>0||parcelBlocked(p)" @click="command(p,d,'retry')">重试下发</el-button><el-button v-if="Number(d.accepted_quantity)>Number(d.posted_quantity)" v-hasPermi="['order:refund:goods']" size="small" @click="command(p,d,'posting')">重试原实收记账</el-button><el-button v-if="d.cancel_state!=='CONFIRMED'&&Number(d.accepted_quantity)<Number(d.quantity)&&refund.goods_state!=='DONE'" v-hasPermi="['order:refund:goods']" size="small" @click="open('cancel',p,d)">截停本次安排剩余数量</el-button><el-button v-if="d.id===documents(p)[0].id&&d.cancel_state==='CONFIRMED'&&remaining(p)>0&&p.state!=='CLOSED'" v-hasPermi="['order:refund:goods']" size="small" :disabled="pendingReviews(p).length>0||parcelBlocked(p)" @click="open('rearrange',p,d)">重新安排剩余退回</el-button><router-link :to="{path:'/oms-supplychain/wmsLogs',query:{numberType:'DOCUMENT',number:d.return_sn,allTime:'true'}}">仓库交互日志</router-link></div></div>
   </template>
   <el-button v-if="remaining(p)>0&&p.state!=='CLOSED'" v-hasPermi="['order:refund:close']" size="small" @click="open('waive',p)">剩余不再追回／差异处理</el-button>
   <template v-if="p.actual"><h4>已分配至本退款的逐次实收与入账</h4><p v-if="!(p.actual.lines||[]).length" class="hint">当前退款单尚无已确认实收；关联包裹待分配实收请进入包裹详情查看。</p><el-table v-if="(p.actual.lines||[]).length" :data="p.actual.lines||[]" empty-text="当前退款单尚无已确认实收；关联包裹待分配实收请进入包裹详情查看"><el-table-column prop="return_sn" label="退回单" min-width="280"/><el-table-column prop="message_id" label="回传消息" min-width="170"/><el-table-column label="SKU / 批次" min-width="180"><template slot-scope="s">{{ s.row.sku_sn }}<div class="hint">{{ s.row.batch_code }}</div></template></el-table-column><el-table-column label="本次良品 / 次品" width="140"><template slot-scope="s">{{ s.row.good_qty }} / {{ s.row.bad_qty }}</template></el-table-column><el-table-column label="记账" width="100"><template slot-scope="s">{{ Number(s.row.posted)?'已入账':'待入账' }}</template></el-table-column></el-table>
    <el-alert v-if="p.actual.parcel_pending_count" title="关联包裹存在实收待分配；本退款尚未确认的部分未入账，请进入包裹详情处理。" type="warning" :closable="false"/><h4 v-if="(p.actual.reviews||[]).length">异常回传 · 人工核对</h4><el-table v-if="(p.actual.reviews||[]).length" :data="p.actual.reviews"><el-table-column prop="return_sn" label="退回单" min-width="280"/><el-table-column prop="message_id" label="消息" min-width="170"/><el-table-column prop="quantity" label="本次数量" width="100"/><el-table-column label="结果" width="110"><template slot-scope="s">{{ ({WAIT_REVIEW:'待人工核对',ACCEPTED:'已确认实收',REJECTED:'已拒绝回传'})[s.row.state] }}</template></el-table-column><el-table-column prop="reason" label="原因 / 依据" min-width="200"/><el-table-column label="操作" width="95"><template slot-scope="s"><el-button v-if="s.row.state==='WAIT_REVIEW'" v-hasPermi="['order:refund:goods']" type="text" @click="open('review',p,documents(p).find(d=>Number(d.id)===Number(s.row.task_id)),s.row)">核对处理</el-button></template></el-table-column></el-table>
   </template>
  </article>
  <refund-parcels ref="parcels" :refund="refund" :plans="plans" @loaded="parcelRows=$event" @changed="parcelChanged" @review="plan=>$refs.issueReview.open(plan)"/>
  <el-dialog :title="titles[action]" :visible.sync="visible" width="min(780px,96vw)" append-to-body :close-on-click-modal="false"><el-alert :title="hint" type="info" :closable="false"/>
   <div v-if="action==='cancel'&&document" class="scope"><b>仅截停：{{ document.return_sn }}</b><p>本次未收 {{ Math.max(0,Number(document.quantity)-Number(document.accepted_quantity)) }} 件；保留已入账 {{ document.posted_quantity }} 件。</p><p>其他退回单继续执行。如需全部停止，请使用计划上的“截停全部未完成安排”。</p></div>
   <div v-if="action==='stop'" class="scope"><b>本计划将逐单申请截停：</b><p v-for="d in activeDocuments(selected)" :key="d.id">第 {{ d.generation }} 次 · {{ d.return_sn }} · 未收 {{ Math.max(0,Number(d.quantity)-Number(d.accepted_quantity)) }} 件</p><p>结果待确认或仓库拒绝时仍保留原安排，请查询核对；待核对回传不会自动接受或拒绝。</p></div>
   <div v-if="action==='review'" class="scope"><b>本次核对：{{ document&&document.return_sn }} · {{ reviewRow.quantity }} 件</b><p>计划 {{ selected.quantity }} 件 · 已确认实收 {{ selected.accepted_quantity }} 件 · 已入账 {{ selected.posted_quantity }} 件</p><p>若确认本次实收，预计仍需退回 {{ Math.max(0,remaining(selected)-Number(reviewRow.quantity||0)) }} 件；须先结束其他安排，确认后按原消息幂等入账，再按剩余量安排。</p><template v-if="activeDocuments(selected).length"><el-alert title="仍有安排在执行，暂不能确认迟到实收。请先截停并核对仓库结果，避免重复退回。" type="warning" :closable="false"/><p v-for="d in activeDocuments(selected)" :key="d.id">第 {{ d.generation }} 次 · {{ d.return_sn }} · 待收 {{ Math.max(0,Number(d.quantity)-Number(d.accepted_quantity)) }} 件</p><el-button size="small" @click="open('stop',selected)">先截停未完成安排</el-button></template><p v-if="form.decision==='REJECT'">拒绝仅表示本次回传不入账，不代表实物已退回或处置完成；请填写仓库核实结果与实物处置凭证。</p></div>
   <div v-if="action==='finish'" class="scope"><b>本次确认货物事项处理完成</b><p>计划合计 {{ total('quantity') }} 件 · 已入账 {{ total('posted_quantity') }} 件 · 不再追回 {{ total('waived_quantity') }} 件</p><el-alert v-if="finishBlockers.length" title="当前不能完成，请先处理以下事项" type="warning" :closable="false"/><p v-for="item in finishBlockers" :key="item">• {{ item }}</p><p v-if="!finishBlockers.length">数量已闭合，退回安排均已结束。请填写最终核对依据。</p><p>此操作不收货、不增加库存、不执行退款。{{ refund.funds_state==='SUCCESS'?'资金已成功，提交后退款单整体完成。':'资金尚未成功，提交后仍需等待资金结果。' }}</p></div>
   <el-form label-width="125px" style="margin-top:20px"><template v-if="action==='logistics'"><el-form-item label="退回运单" required><el-input v-model.trim="form.return_waybill" maxlength="128"/></el-form-item><el-form-item label="物流状态"><el-select v-model="form.transport_state"><el-option v-for="(v,k) in transportStates" :key="k" :value="k" :label="v"/></el-select></el-form-item></template><template v-if="action==='create'"><el-form-item label="实际发货来源" required><el-select v-model="form.shipment_line_id" style="width:100%"><el-option v-for="s in refund.shipments.filter(s=>Number(s.shipped_quantity)>0)" :key="s.shipment_line_id" :value="s.shipment_line_id" :label="`${s.shipment_sn} · #${s.shipment_line_id} · ${s.sku_sn} · 已出库${s.shipped_quantity}件`"/></el-select></el-form-item><el-form-item label="本次应退数量" required><el-input-number v-model="form.quantity" :min="1" :max="100000000" :precision="0"/></el-form-item></template><template v-if="['create','rearrange'].includes(action)"><el-form-item label="接收虚拟仓" required><el-select v-model="form.store_code" filterable><el-option v-for="w in warehouses" :key="w.code" :value="w.code" :label="`${w.name||w.code} (${w.code})`"/></el-select></el-form-item><el-form-item label="寄回地址" required><el-input v-model.trim="form.return_address" maxlength="500"/></el-form-item><el-form-item label="寄回联系信息" required><el-input v-model.trim="form.return_contact" maxlength="200"/></el-form-item></template><el-form-item v-if="action==='cancel'" label="截单目的"><el-radio-group v-model="form.mode"><el-radio label="WITHDRAW">撤回重新安排</el-radio><el-radio label="TERMINATE">终止剩余安排</el-radio></el-radio-group></el-form-item><el-form-item v-if="action==='review'" label="核对结论"><el-radio-group v-model="form.decision"><el-radio label="REJECT">拒绝本次回传</el-radio><el-radio label="ACCEPT" :disabled="activeDocuments(selected).length>0">确认真实实收</el-radio></el-radio-group></el-form-item><el-form-item v-if="action==='waive'" label="未追回数量">{{ remaining(selected) }} 件；不会增加库存</el-form-item><el-form-item label="处理依据" required><el-input v-model.trim="form.reason" type="textarea" :maxlength="action==='review'?200:500"/></el-form-item><el-form-item label="核对凭证" required><el-input v-model.trim="form.evidence" type="textarea" :maxlength="action==='review'?250:1000"/></el-form-item><el-form-item><el-checkbox v-model="form.confirmed">已核对实际商品、处理范围、数量与凭证</el-checkbox></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">返回</el-button><el-button type="primary" :loading="busy" :disabled="!form.confirmed||(action==='finish'&&finishBlockers.length>0)||(action==='review'&&form.decision==='ACCEPT'&&activeDocuments(selected).length>0)" @click="submit">确认提交</el-button></span></el-dialog>
 </section>
</template>
<script>
import * as api from '@/api/order/refund'
import RefundParcels from './RefundParcels'
import RefundParcelIssueReview from './RefundParcelIssueReview'
import { label } from './refundLabels'
import { receiptText, sourcePending } from './refundParcelPresentation'
import { documents, activeDocuments, pendingReviews, pendingQuantity, remaining, completionBlockers } from './refundGoodsPresentation'
export default {name:'RefundGoods',components:{RefundParcels,RefundParcelIssueReview},props:{refund:{type:Object,required:true}},data:()=>({loading:false,busy:false,error:'',plans:[],parcelRows:[],sequence:0,visible:false,action:'',selected:{},document:null,reviewRow:{},form:{},warehouses:[],transportStates:{WAITING:'待退回',IN_TRANSIT:'退回在途',REFUSED:'已拒收待退回',INTERCEPTED:'已拦截待退回',DELIVERED:'物流已签收（非仓库实收）'},titles:{logistics:'登记退回物流',cancelUnshipped:'执行已审核的未发取消',create:'创建退款退回安排',cancel:'截停本次安排剩余数量',stop:'截停本计划全部未完成安排',rearrange:'重新安排剩余退回',review:'核对异常实收',waive:'剩余不再追回',waiveAll:'确认无需追回',finish:'确认货物处理完成',closeWithdrawn:'确认申请关闭后的货物处置'}}),computed:{finishBlockers(){return completionBlockers(this.plans)},returnRequired(){return ['REFUSAL','INTERCEPT','RETURN'].includes(this.refund.goods_action)},hint(){return this.action==='review'?'先核实仓库实物与原消息。确认迟到实收前须截停其他安排；拒绝回传不代表实物已经处理。':['waive','waiveAll'].includes(this.action)?'此操作仅记录不再追回的依据，不伪造收货、不增加库存。已有仓库安排必须先确认截停。':this.action==='closeWithdrawn'?'仅结束平台已关闭申请的货物事项。必须先结束所有仓库安排、完成实收入账及待核对回传；已入账库存保留，剩余终止追回，必须填写实物处置凭证。':this.action==='finish'?'这是退款货物事项的最终确认，不是仓库收货或质检操作；所有未完成事项处理后才能提交。':'按实际发货明细安排。创建及下发不会增加库存；截单只停止仓库剩余收货，不代表已拦截物流。'}},watch:{refund(){this.load()}},created(){this.load()},beforeDestroy(){this.sequence++},methods:{receiptText,
planPending(p){return Number((p.actual||{}).parcel_pending_count)>0||this.parcelRows.some(parcel=>(parcel.members||[]).some(m=>Number(m.plan_id)===Number(p.id)&&sourcePending(parcel,m)))},
sharedPlan(p){return p.parcel_state==='LINKED'||!!(p.actual&&p.actual.shared_document)},
openParcel(plan){return this.$refs.parcels.openForPlan(plan)},
openParcels(){return this.$refs.parcels.openFirst()},
parcelBlocked(p){return p.parcel_state==='NEED_CHECK'||['WAIT_BUYER','WAREHOUSE_CHECK'].includes(p.parcel_resolution)},async startParcelWaive(id){await this.load();const p=this.plans.find(p=>Number(p.id)===Number(id));if(p)this.open('waive',p);else this.$message.warning('退回计划已变化，请刷新核对')},async parcelChanged(){await this.refresh()},label,remaining,activeDocuments,pendingReviews,pendingQuantity,total(key){return this.plans.reduce((n,p)=>n+Number(p[key]||0),0)},planLabel(s){return ({PLANNED:'待下发',ACTIVE:'待仓库收货',PARTIAL:'部分实收',STOPPED:'安排已结束',WAIT_REVIEW:'待人工核对',CLOSED:'已处理'})[s]||s},documents,dispatch(d){return d.cancel_state==='CONFIRMED'?'剩余已截停':({PENDING:'待下发',SENDING:'下发中',ACCEPTED:'仓库已接收',UNKNOWN:'结果待确认',FAILED:'下发失败',CANCELED:'安排已停止'})[d.dispatch_state]||d.dispatch_state},async load(){const seq=++this.sequence;this.loading=true;try{const r=(await api.refundGoods(this.refund.id)).data;if(seq===this.sequence){this.plans=r.plans;this.error=''}}catch(_){if(seq===this.sequence)this.error='退回安排加载失败，请刷新核对'}finally{if(seq===this.sequence)this.loading=false}},async refresh(){if(this.busy)return;this.busy=true;try{await api.refreshRefundGoods(this.refund.id);this.$emit('changed');await this.load()}finally{this.busy=false}},async open(action,p={},d=null,review=null){if(p.actual&&p.actual.shared_document&&['cancel','stop','rearrange'].includes(action))return this.$message.warning('这是共同THK，请在退回包裹中确认整单影响后操作');this.action=action;this.selected=p;this.document=d;this.reviewRow=review||{};this.form={request_key:'RET_'+Date.now()+'_'+Math.random().toString(16).slice(2),quantity:action==='waive'?this.remaining(p):1,shipment_line_id:undefined,store_code:d&&d.store_code||p.store_code||'',return_address:d&&d.return_address||p.return_address||'',return_contact:d&&d.return_contact||p.return_contact||'',return_waybill:p.return_waybill||'',transport_state:p.transport_state||'WAITING',reason:'',evidence:'',mode:'WITHDRAW',decision:'REJECT',review_id:review&&review.id,confirmed:false};if(['create','rearrange'].includes(action))this.warehouses=(await api.refundGoodsOptions(this.refund.id)).data.warehouses;this.visible=true},async command(p,d,action,body={}){if((p.actual&&p.actual.shared_document&&['cancel','rearrange','stop','retry','dispatch'].includes(action))||(!p.actual&&p.parcel_state==='LINKED'&&action==='dispatch'))return this.$message.warning('请到上方退回包裹核对全部退款并统一处理共同THK');if(this.busy)return;this.busy=true;try{await api.refundGoodsAction(this.refund.id,p.id,d&&d.id||0,action,{...body,control_version:this.refund.control_version,plan_version:p.control_version,document_version:d&&d.control_version});this.visible=false;this.$emit('changed');await this.load()}finally{this.busy=false}},async submit(){if(!this.form.reason||!this.form.evidence)return this.$message.warning('请填写处理依据和核对凭证');if(this.action==='create'||['finish','waiveAll','cancelUnshipped','closeWithdrawn'].includes(this.action)){if(this.busy)return;this.busy=true;try{const fn=this.action==='create'?api.createRefundReturn:this.action==='cancelUnshipped'?api.cancelRefundUnshipped:this.action==='finish'?api.finishRefundGoods:this.action==='closeWithdrawn'?api.closeWithdrawnRefund:api.waiveRefundGoods;await fn(this.refund.id,{...this.form,control_version:this.refund.control_version});this.visible=false;this.$emit('changed');await this.load()}finally{this.busy=false}}else return this.command(this.selected,this.document,this.action,{...this.form,...(this.action==='rearrange'?{quantity:this.remaining(this.selected)}:{})})}}}
</script>
